const searchSources = `-- name: SearchSources :many
SELECT d.organization_id, d.id, d.project_id, d.work_item_id, d.kind, d.source_id, d.comment_id, d.event_id, d.change_id, d.revision, d.indexed_revision, d.title, d.scope, d.status, d.updated_at, d.updated_at_submicrosecond, d.payload_object_key, d.payload_sha256, d.payload_bytes, d.payload_content_bytes, d.vector, d.token_count, d.terms, d.term_frequencies, d.refresh_order, d.source_vector, d.generation, d.source_visible, d.placeholder, d.aggregate_object_key, d.aggregate_sha256, d.aggregate_bytes, d.aggregate_content_bytes, d.progress_generation, d.progress_after_id, d.progress_object_key, d.progress_sha256, d.progress_bytes, d.progress_content_bytes FROM search_documents d
WHERE d.organization_id=$1 AND d.project_id=$2 AND d.work_item_id=$3
 AND d.kind NOT IN ('issue','thread') AND d.source_visible AND d.id COLLATE "C">$4 COLLATE "C"
 AND (d.kind<>'comment' OR EXISTS(SELECT 1 FROM native_comments c WHERE c.organization_id=d.organization_id AND c.id=d.source_id AND NOT c.deleted))
ORDER BY d.id COLLATE "C" LIMIT $5
`

type SearchSourcesParams struct {
	OrganizationID tracker.OrganizationID
	ProjectID      *tracker.ProjectID
	WorkItemID     *string
	AfterID        string
	PageSize       int32
}

func (q *Queries) SearchSources(ctx context.Context, arg SearchSourcesParams) ([]SearchDocument, error) {
	rows, err := q.db.QueryContext(ctx, searchSources,
		arg.OrganizationID,
		arg.ProjectID,
		arg.WorkItemID,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchDocument{}
	for rows.Next() {
		var i SearchDocument
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ID,
			&i.ProjectID,
			&i.WorkItemID,
			&i.Kind,
			&i.SourceID,
			&i.CommentID,
			&i.EventID,
			&i.ChangeID,
			&i.Revision,
			&i.IndexedRevision,
			&i.Title,
			&i.Scope,
			&i.Status,
			&i.UpdatedAt,
			&i.UpdatedAtSubmicrosecond,
			&i.PayloadObjectKey,
			&i.PayloadSHA256,
			&i.PayloadBytes,
			&i.PayloadContentBytes,
			&i.Vector,
			&i.TokenCount,
			pq.Array(&i.Terms),
			pq.Array(&i.TermFrequencies),
			&i.RefreshOrder,
			&i.SourceVector,
			&i.Generation,
			&i.SourceVisible,
			&i.Placeholder,
			&i.AggregateObjectKey,
			&i.AggregateSha256,
			&i.AggregateBytes,
			&i.AggregateContentBytes,
			&i.ProgressGeneration,
			&i.ProgressAfterID,
			&i.ProgressObjectKey,
			&i.ProgressSha256,
			&i.ProgressBytes,
			&i.ProgressContentBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

